.gfh-brief { padding: clamp(20px, 3vw, 32px); border-radius: 16px; background-image: linear-gradient(160deg, #e3f2ef, #d2ebe5); } .gfh-brief-k { margin-bottom: 10px; color: #0a524e; font-size: 13px; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; } .dcw-statement.is-brief { font-size: clamp(19px, 1.9vw, 23px); } .dcw-p.is-flush { margin-bottom: 0; } .gfh-deliv { display: grid; grid-template-columns: repeat(5, 1fr); grid-column-gap: 12px; grid-row-gap: 12px; } .gfh-deliv-card { display: flex; flex-direction: column; padding: 18px 18px 16px; border: 1px solid #e2e2e2; border-radius: 14px; background-color: #ffffff; box-shadow: 0 1px 2px rgba(6,43,42,0.04), 0 10px 24px -16px rgba(6,43,42,0.25); } .gfh-deliv-title { margin-bottom: 6px; color: #111111; font-size: 16px; font-weight: 600; } .gfh-deliv-text { margin-top: 0; margin-bottom: 0; color: #3d3d3d; font-size: 15px; line-height: 1.45; } .gfh-deliv-link { margin-top: auto; padding-top: 12px; color: #0f6e68; font-size: 13px; font-weight: 600; text-decoration: none; } .gfh-constraint { display: flex; align-items: flex-start; grid-column-gap: 14px; max-width: 760px; margin-top: 32px; padding: 16px 18px; border: 1px solid #e2e2e2; border-left: 4px solid #0f6e68; border-radius: 10px; background-color: #ffffff; } .gfh-badge { flex: none; margin-top: 2px; padding: 3px 8px; border: 1px solid #0a524e; border-radius: 999px; color: #0a524e; font-size: 11px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; } .gfh-constraint-text { margin-top: 0; margin-bottom: 0; color: #3d3d3d; font-size: 15px; line-height: 1.6; } .gfh-draft.is-sm { margin-top: 10px; padding: 8px 10px; font-size: 13px; }
@media screen and (max-width: 991px) { .gfh-deliv { grid-template-columns: repeat(3, 1fr); } }
@media screen and (max-width: 767px) { .gfh-deliv { grid-template-columns: 1fr 1fr; } .gfh-constraint { flex-direction: column; grid-row-gap: 8px; } }
@media screen and (max-width: 479px) { .gfh-deliv { grid-template-columns: 1fr; } }

.gfh-view.is-preview { max-height: 440px; } .gfh-fig { display: flex; flex-direction: column; min-width: 0; } .gfh-cap { margin-top: 14px; } .gfh-cap-title { margin-bottom: 3px; color: #111111; font-size: 15px; font-weight: 600; line-height: 1.35; } .gfh-cap-text { margin-top: 0; margin-bottom: 0; color: #5f5f5f; font-size: 14px; line-height: 1.5; } .gfh-trio { display: grid; grid-template-columns: 1fr 1fr 1fr; grid-column-gap: clamp(24px, 4vw, 56px); grid-row-gap: 40px; align-items: start; }
@media screen and (max-width: 991px) { .gfh-trio { grid-column-gap: 16px; } }
@media screen and (max-width: 767px) { .gfh-trio { grid-template-columns: 1fr; grid-row-gap: 40px; } .gfh-fig { width: 100%; max-width: 380px; margin-left: auto; margin-right: auto; } }

.gfh-focus { display: grid; grid-template-columns: repeat(4, 1fr); grid-column-gap: 12px; grid-row-gap: 12px; } .gfh-focus-card { padding: 16px 18px; border: 1px solid #e2e2e2; border-radius: 12px; background-color: #ffffff; } .gfh-wf-frame { padding: 12px; border: 1px solid #e2e2e2; border-radius: 14px; background-color: #ffffff; }
@media screen and (max-width: 991px) { .gfh-focus { grid-template-columns: 1fr 1fr; } }
@media screen and (max-width: 767px) { .gfh-focus { grid-template-columns: 1fr; } }

.gfh-view.is-compare { max-height: 380px; } .gfh-note.is-head { max-width: 760px; margin-top: -24px; margin-bottom: 40px; } .gfh-decision { display: grid; grid-template-columns: 5fr 7fr; grid-column-gap: clamp(28px, 5vw, 72px); grid-row-gap: 28px; margin-bottom: clamp(40px, 5vw, 64px); padding-bottom: clamp(40px, 5vw, 64px); border-bottom: 1px solid #e2e2e2; } .gfh-theme-num { margin-bottom: 6px; color: #0f6e68; font-family: Inconsolata, monospace; font-size: 13px; font-weight: 700; } .gfh-decision-title { margin-top: 0; margin-bottom: 18px; color: #111111; font-size: 20px; font-weight: 600; line-height: 1.3; } .gfh-intended { display: inline-block; margin-top: 10px; padding: 1px 8px; border: 1px dashed #c9c9c9; border-radius: 999px; color: #5f5f5f; font-size: 12px; font-weight: 600; } .gfh-cmp { display: grid; grid-template-columns: 1fr 1fr; grid-column-gap: clamp(16px, 3vw, 32px); grid-row-gap: 24px; align-items: start; } .gfh-cmp-item { display: flex; flex-direction: column; align-items: flex-start; min-width: 0; } .gfh-draft.is-in-chain { margin-top: 10px; padding: 8px 10px; font-size: 13px; }
@media screen and (max-width: 991px) { .gfh-decision { grid-template-columns: 1fr; } }
@media screen and (max-width: 767px) { .gfh-cmp { grid-template-columns: 1fr; } .gfh-view.is-compare { max-height: 320px; } }
